// Avoid: unbounded raw threads
for (int i = 0; i < 10_000; i++) {
    new Thread(() -> process(i)).start(); // 10,000 OS threads!
}

// Better: a bounded pool reuses a fixed set of workers
try (ExecutorService pool = Executors.newFixedThreadPool(8)) {
    for (int i = 0; i < 10_000; i++) {
        int taskId = i;
        pool.submit(() -> process(taskId));
    }
} // pool.close() waits for tasks and shuts the pool down

class Counter {
    private int count = 0;

    // synchronized: mutual exclusion AND visibility
    public synchronized void increment() {
        count++;
    }
    public synchronized int get() {
        return count;
    }
}

class Flag {
    // volatile: visibility only — fine for a simple flag,
    // NOT enough for a compound operation like count++
    private volatile boolean stopRequested = false;

    void requestStop() { stopRequested = true; }
    boolean shouldStop() { return stopRequested; }
}

class Counter {
    private final AtomicInteger count = new AtomicInteger(0);

    void increment() {
        count.incrementAndGet(); // lock-free, CAS-based
    }
    int get() {
        return count.get();
    }
}

// compareAndSet: only updates if the value matches what you expect
AtomicInteger state = new AtomicInteger(0);
boolean updated = state.compareAndSet(0, 1); // true, was 0
boolean failed  = state.compareAndSet(0, 2); // false, now 1 not 0
